47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.samples.petclinic.util.Households;
50	import org.springframework.samples.petclinic.util.Localities;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
70	     * new owner's id, its assigned {@code customerCode}, its {@code registrationDate} and its
71	     * numeric {@code membershipLevel}.
72	     */
73	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    public OwnerRestControllerV1(ClinicService clinicService,
84	                                 OwnerMapper ownerMapper,
85	                                 PetMapper petMapper,
86	                                 VisitMapper visitMapper) {
87	        this.clinicService = clinicService;
88	        this.ownerMapper = ownerMapper;
89	        this.petMapper = petMapper;
90	        this.visitMapper = visitMapper;
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
96	        Collection<Owner> owners;
97	        if (lastName != null) {
98	            owners = this.clinicService.findOwnerByLastName(lastName);
99	        } else {
100	            owners = this.clinicService.findAllOwners();
101	        }
102	        if (owners.isEmpty()) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
111	        Owner owner = this.clinicService.findOwnerById(ownerId);
112	        if (owner == null) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
124	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
125	        rejectFutureRegistrationDate(registrationDate);
126	        if (registrationDate == null) {
127	            registrationDate = java.time.LocalDate.now();
128	        }
129	        registrationDate = toBusinessDay(registrationDate);
130	        owner.setRegistrationDate(registrationDate);
131	        rejectDailyLimitReached(registrationDate);
132	        rejectCityAtCapacity(owner.getCity());
133	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
134	        owner.setTelephone(telephone);
135	        String email = normalizeEmail(ownerFieldsDto.getEmail());
136	        owner.setEmail(email);
137	        owner.setPostcode(validatePostcode(owner.getCity(), ownerFieldsDto.getPostcode()));
138	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
139	        rejectDuplicateIdentity(owner);
140	        rejectDuplicateHousehold(owner, sharesHousehold);
141	        String region = Localities.region(owner.getPostcode(), owner.getCity());
142	        owner.setCustomerCode(assignCustomerCode(region, owner.getTelephone(), owner.getLastName()));
143	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
144	        owner.setBulkSignupWarning(computeBulkSignupWarning(registrationDate));
145	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getPostcode()) + 1);
146	        // A declared household member (sharesHousehold) is created but is not a suspected duplicate.
147	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicateOf(owner);
148	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
149	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
150	        this.clinicService.saveOwner(owner);
151	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
152	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
153	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
154	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
155	        headers.setLocation(UriComponentsBuilder.newInstance()
156	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
157	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
158	    }
159	
160	    /**
161	     * Rejects creating an owner whose supplied {@code registrationDate} is later than the server
162	     * date (in the future). Only an explicitly supplied date is validated; a {@code null} date
163	     * (which later defaults to the server date) is accepted. The check is against the raw supplied
164	     * date, before any business-day adjustment.
165	     *
166	     * @param registrationDate the supplied registration date, or {@code null} when none was supplied
167	     * @throws FutureRegistrationDateException (400 Bad Request) if the supplied date is in the future
168	     */
169	    private void rejectFutureRegistrationDate(java.time.LocalDate registrationDate) {
170	        if (registrationDate != null && registrationDate.isAfter(java.time.LocalDate.now())) {
171	            throw new FutureRegistrationDateException(registrationDate);
172	        }
173	    }
174	
175	    /**
176	     * The maximum number of owners that may be created in a single day. Creating an owner once this
177	     * many owners already carry today's {@code registrationDate} is rejected.
178	     */
179	    private static final int DAILY_OWNER_LIMIT = 100;
180	
181	    /**
182	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
183	     * given business day as their {@code registrationDate}. The count is keyed by the
184	     * business-day-adjusted registration date of the owner being created (see
185	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
186	     * with no {@code registrationDate} are ignored.
187	     *
188	     * @param registrationDate the business-day-adjusted registration date of the owner being created
189	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
190	     */
191	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
192	        long count = this.clinicService.findAllOwners().stream()
193	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
194	            .count();
195	        if (count >= DAILY_OWNER_LIMIT) {
196	            throw new DailyOwnerLimitException(registrationDate);
197	        }
198	    }
199	
200	    /**
201	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
202	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
203	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
204	     */
205	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
206	
207	    /**
208	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
209	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
210	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
211	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
212	     * owner being created is excluded (it has not yet been saved).
213	     *
214	     * @param registrationDate the business-day-adjusted registration date of the owner being created
215	     * @return {@code true} if more than the threshold of owners already carry this business day
216	     */
217	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
218	        long count = this.clinicService.findAllOwners().stream()
219	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
220	            .count();
221	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
222	    }
223	
224	    /**
225	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is moved forward to
226	     * the following Monday; a weekday is returned unchanged. This applies to the effective
227	     * registration date whether it was supplied in the request or defaulted to the server date, and
228	     * every value derived from the registration date uses the adjusted result.
229	     *
230	     * @param date the effective registration date
231	     * @return {@code date} itself when it is a weekday, otherwise the following Monday
232	     */
233	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
234	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
235	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
236	            date = date.plusDays(1);
237	        }
238	        return date;
239	    }
240	
241	    /**
242	     * The maximum number of owners a single city may contain. Creating an owner in a city that
243	     * already holds this many owners is rejected.
244	     */
245	    private static final int CITY_CAPACITY = 50;
246	
247	    /**
248	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
249	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
250	     * treated as empty).
251	     *
252	     * @param city the city of the owner being created
253	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
254	     */
255	    private void rejectCityAtCapacity(String city) {
256	        String cityValue = city == null ? "" : city;
257	        long count = this.clinicService.findAllOwners().stream()
258	            .filter(existing -> cityValue.equalsIgnoreCase(
259	                existing.getCity() == null ? "" : existing.getCity()))
260	            .count();
261	        if (count >= CITY_CAPACITY) {
262	            throw new CityAtCapacityException(city);
263	        }
264	    }
265	
266	    /**
267	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<REGION>-<HASH8>'} where
268	     * REGION is the owner's canonical region (derived by preferring the postcode, see
269	     * {@link Localities#region(String, String)} — the same region derivation shared with the
270	     * {@code locality}) and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest of
271	     * the normalized (E.164) telephone concatenated with the last name (e.g. {@code 'NSW-3A7F9C2E'}).
272	     * The code is derived from the owner's own identity fields; it carries no sequence number.
273	     * <p>
274	     * When the computed code collides with an existing owner's {@code customerCode}, it is
275	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes
276	     * it unique (e.g. {@code 'NSW-3A7F9C2E-2'}), and the de-duplicated code is returned.
277	     *
278	     * @param region the owner's canonical region (the identity's REGION, shared with the locality)
279	     * @param telephone the owner's normalized (E.164) telephone
280	     * @param lastName the owner's last name
281	     * @return the assigned customer code, de-duplicated to be unique among existing owners
282	     */
283	    private String assignCustomerCode(String region, String telephone, String lastName) {
284	        String basis = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
285	        String hash8 = sha256UpperHex(basis).substring(0, 8);
286	        String code = region + "-" + hash8;
287	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
288	            .map(Owner::getCustomerCode)
289	            .filter(java.util.Objects::nonNull)
290	            .collect(java.util.stream.Collectors.toSet());
291	        if (!existing.contains(code)) {
292	            return code;
293	        }
294	        for (int n = 2; ; n++) {
295	            String candidate = code + "-" + n;
296	            if (!existing.contains(candidate)) {
297	                return candidate;
298	            }
299	        }
300	    }
301	
302	    /**
303	     * Returns the full upper-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
304	     */
305	    private static String sha256UpperHex(String value) {
306	        try {
307	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
308	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
309	            StringBuilder sb = new StringBuilder(digest.length * 2);
310	            for (byte b : digest) {
311	                sb.append(String.format("%02X", b));
312	            }
313	            return sb.toString();
314	        }
315	        catch (java.security.NoSuchAlgorithmException e) {
316	            throw new IllegalStateException("SHA-256 not available", e);
317	        }
318	    }
319	
320	    /**
321	     * Counts how many existing owners share the given first and last name, compared
322	     * case-insensitively, at the time this owner is created. The value excludes the owner
323	     * being created (which has not yet been saved) and is stored on the new owner and returned
324	     * as its {@code namesakeCount}.
325	     *
326	     * @param firstName the first name of the owner being created
327	     * @param lastName the last name of the owner being created
328	     * @return the number of existing owners with the same first and last name
329	     */
330	    private int countNamesakes(String firstName, String lastName) {
331	        String first = firstName == null ? "" : firstName;
332	        String last = lastName == null ? "" : lastName;
333	        return (int) this.clinicService.findAllOwners().stream()
334	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
335	                && last.equalsIgnoreCase(existing.getLastName()))
336	            .count();
337	    }
338	
339	    /**
340	     * Counts how many existing owners belong to the same household as the owner being created, i.e.
341	     * share its {@code householdId} (derived by {@link Households#householdId} from the normalized last
342	     * name and postcode). The value excludes the owner being created (which has not yet been saved), so
343	     * the household's size after this create is this count plus one. It is stored on the new owner.
344	     *
345	     * @param lastName the last name of the owner being created
346	     * @param postcode the postcode of the owner being created
347	     * @return the number of existing owners sharing this owner's household
348	     */
349	    private int countHouseholdMembers(String lastName, String postcode) {
350	        String householdId = Households.householdId(lastName, postcode);
351	        return (int) this.clinicService.findAllOwners().stream()
352	            .filter(existing -> householdId.equals(
353	                Households.householdId(existing.getLastName(), existing.getPostcode())))
354	            .count();
355	    }
356	
357	    /**
358	     * Rejects creating an owner that would join an existing household without opting in. The household
359	     * is keyed on the computed {@code householdId} (see {@link Households#householdId}, derived from the
360	     * normalized last name and postcode), so an owner sharing an existing owner's last name and postcode
361	     * is the same household. When another owner already belongs to that household the create is rejected,
362	     * unless the request opts in with {@code sharesHousehold}, which bypasses this block and creates the
363	     * owner as a declared household member. An owner with no postcode is never treated as a household
364	     * duplicate.
365	     *
366	     * @param owner the owner being created, with its last name and postcode already set
367	     * @param sharesHousehold whether the request opted in via {@code sharesHousehold}
368	     * @throws DuplicateHouseholdException (409 Conflict) if the owner joins an existing household and did
369	     *         not opt in
370	     */
371	    private void rejectDuplicateHousehold(Owner owner, boolean sharesHousehold) {
372	        if (sharesHousehold) {
373	            return;
374	        }
375	        String postcode = owner.getPostcode();
376	        if (postcode == null) {
377	            return;
378	        }
379	        String householdId = Households.householdId(owner.getLastName(), postcode);
380	        boolean exists = this.clinicService.findAllOwners().stream()
381	            .anyMatch(existing -> householdId.equals(
382	                Households.householdId(existing.getLastName(), existing.getPostcode())));
383	        if (exists) {
384	            throw new DuplicateHouseholdException(owner.getLastName(), postcode);
385	        }
386	    }
387	
388	    /**
389	     * Finds the existing owner, if any, that the owner being created is a soft duplicate of: an owner
390	     * sharing this owner's last name (compared case-insensitively) and postcode (an exact match of the
391	     * stored 4-digit value) while carrying a <em>different</em> telephone. A soft match is distinct from
392	     * the hard duplicate rejected earlier by {@link #rejectDuplicateIdentity}: the owner is still
393	     * created, but flagged. When more than one existing owner matches, the earliest (lowest id) is
394	     * returned so the reference is deterministic. An owner with no postcode can never soft-match.
395	     *
396	     * @param owner the owner being created, with its telephone and postcode already normalized/validated
397	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
398	     */
399	    private Integer findPossibleDuplicateOf(Owner owner) {
400	        String postcode = owner.getPostcode();
401	        if (postcode == null) {
402	            return null;
403	        }
404	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
405	        String telephone = owner.getTelephone();
406	        return this.clinicService.findAllOwners().stream()
407	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
408	            .filter(existing -> postcode.equals(existing.getPostcode()))
409	            .filter(existing -> !java.util.Objects.equals(telephone, existing.getTelephone()))
410	            .map(Owner::getId)
411	            .filter(java.util.Objects::nonNull)
412	            .min(java.util.Comparator.naturalOrder())
413	            .orElse(null);
414	    }
415	
416	    /**
417	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
418	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
419	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
420	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
421	     * {@code "+61412345678"}. The E.164 value is stored and returned.
422	     * <p>
423	     * The national-number length (the digits after the country code) is additionally validated for
424	     * country codes with a fixed length: '+61' requires exactly 9 national digits and '+1' requires
425	     * exactly 10. Numbers of other country codes are only bound by the overall 8-to-15-digit limit.
426	     *
427	     * @param telephone the raw telephone as submitted
428	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
429	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
430	     *         or its national-number length is wrong for its country code
431	     */
432	    private String normalizeTelephone(String telephone) {
433	        String raw = telephone == null ? "" : telephone.trim();
434	        boolean hasCountryCode = raw.startsWith("+");
435	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
436	        if (hasCountryCode) {
437	            cleaned = cleaned.substring(1);
438	        }
439	        String digits;
440	        if (hasCountryCode) {
441	            digits = cleaned;
442	        } else {
443	            if (cleaned.startsWith("0")) {
444	                cleaned = cleaned.substring(1);
445	            }
446	            digits = "61" + cleaned;
447	        }
448	        if (!digits.matches("[0-9]{8,15}") || !hasValidNationalLength(digits)) {
449	            throw new InvalidTelephoneException(telephone);
450	        }
451	        return "+" + digits;
452	    }
453	
454	    /**
455	     * Checks the national-number length of an E.164 digit string against its country code for the
456	     * country codes whose national number has a fixed length: '+61' requires 9 national digits and
457	     * '+1' requires 10. Any other country code passes, leaving it bound only by the overall length.
458	     *
459	     * @param digits the E.164 digits (the country code followed by the national number, without '+')
460	     * @return {@code true} if the national-number length is acceptable for the country code
461	     */
462	    private boolean hasValidNationalLength(String digits) {
463	        if (digits.startsWith("61")) {
464	            return digits.length() - 2 == 9;
465	        }
466	        if (digits.startsWith("1")) {
467	            return digits.length() - 1 == 10;
468	        }
469	        return true;
470	    }
471	
472	    /**
473	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
474	     * multi-character top-level label. Deliberately lenient about the exact character set while still
475	     * rejecting values that are clearly not addresses (e.g. missing '@').
476	     */
477	    private static final java.util.regex.Pattern EMAIL_PATTERN =
478	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
479	
480	    /**
481	     * Domains of known disposable/throwaway email providers. An owner whose email domain is on this
482	     * blocklist is rejected with a 400 Bad Request. Compared case-insensitively against the
483	     * lower-cased email domain.
484	     */
485	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
486	        "mailinator.com", "tempmail.com", "guerrillamail.com");
487	
488	    /**
489	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
490	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
491	     * lower-cased before being stored and returned.
492	     *
493	     * @param email the raw email as submitted, may be {@code null}
494	     * @return the lower-cased email, or {@code null} when none was supplied
495	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
496	     */
497	    private String normalizeEmail(String email) {
498	        if (email == null || email.isBlank()) {
499	            return null;
500	        }
501	        String trimmed = email.trim();
502	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
503	            throw new InvalidEmailException(email);
504	        }
505	        String normalized = trimmed.toLowerCase(java.util.Locale.ROOT);
506	        String domain = normalized.substring(normalized.indexOf('@') + 1);
507	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
508	            throw new DisposableEmailException(email);
509	        }
510	        return normalized;
511	    }
512	
513	    /**
514	     * Fixed region-to-postcode-range table: a region's postcode must fall within its inclusive range
515	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose region is not listed here (see
516	     * {@link Localities#region}) accepts any 4-digit postcode.
517	     */
518	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
519	        "NSW", new int[] {2000, 2099},
520	        "VIC", new int[] {3000, 3099},
521	        "QLD", new int[] {4000, 4099});
522	
523	    /**
524	     * Validates an owner's postcode on create. The postcode is optional: a {@code null} or blank value
525	     * is left as {@code null} (no postcode) and accepted. When present it must be exactly 4 digits and,
526	     * for a city whose region is in the fixed {@link #REGION_POSTCODE_RANGES range table}, must fall
527	     * within that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no
528	     * known region accepts any 4-digit postcode. The value is stored and returned exactly as supplied.
529	     *
530	     * @param city the owner's city, used to derive the region whose range constrains the postcode
531	     * @param postcode the raw postcode as submitted, may be {@code null}
532	     * @return the postcode when supplied, or {@code null} when none was supplied
533	     * @throws InvalidPostcodeException (400 Bad Request) if a supplied postcode is not 4 digits or is
534	     *         out of range for the city's region
535	     */
536	    private String validatePostcode(String city, String postcode) {
537	        if (postcode == null || postcode.isBlank()) {
538	            return null;
539	        }
540	        if (!postcode.matches("[0-9]{4}")) {
541	            throw new InvalidPostcodeException(postcode);
542	        }
543	        int[] range = REGION_POSTCODE_RANGES.get(Localities.region(city));
544	        if (range != null) {
545	            int value = Integer.parseInt(postcode);
546	            if (value < range[0] || value > range[1]) {
547	                throw new InvalidPostcodeException(postcode);
548	            }
549	        }
550	        return postcode;
551	    }
552	
553	    /**
554	     * Common street-type abbreviations expanded to their full word during address normalization.
555	     */
556	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
557	        "ST", "STREET",
558	        "RD", "ROAD",
559	        "AVE", "AVENUE");
560	
561	    /**
562	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
563	     * whitespace collapse to a single space, the value is upper-cased and common street-type
564	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
565	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
566	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
567	     * for every address comparison (household duplicate detection and the shared household id).
568	     *
569	     * @param address the raw address as submitted
570	     * @return the normalized address
571	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
572	     */
573	    private String normalizeAddress(String address) {
574	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
575	        if (collapsed.isEmpty()) {
576	            throw new InvalidAddressException(address);
577	        }
578	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
579	        StringBuilder normalized = new StringBuilder(collapsed.length());
580	        for (int i = 0; i < tokens.length; i++) {
581	            if (i > 0) {
582	                normalized.append(' ');
583	            }
584	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
585	        }
586	        return normalized.toString();
587	    }
588	
589	    /**
590	     * Rejects creating an owner whose identity duplicates an existing owner's. All duplicate detection
591	     * is consolidated here onto the identity-bearing part of the derived {@code identityKey}: two
592	     * owners are duplicates when they share the same normalized telephone and the same normalized email
593	     * (a {@code null} email compared as an empty segment). Existing telephones are re-normalized to
594	     * E.164 and existing emails lower-cased before comparison, so equivalent values submitted in
595	     * different formats (e.g. national {@code "0412 345 678"} and international {@code "+61 412 345 678"})
596	     * still match.
597	     * <p>
598	     * The {@code householdId} is deliberately not part of this comparison: a household is a shared
599	     * grouping, so two members of the same household with different telephones have different
600	     * identities and are both allowed. Only owners with the same telephone and email collide.
601	     *
602	     * @param owner the owner being created, with its telephone and email already normalized
603	     * @throws DuplicateIdentityException (409 Conflict) if another owner has the same identity
604	     */
605	    private void rejectDuplicateIdentity(Owner owner) {
606	        String identity = personalIdentity(owner.getTelephone(), owner.getEmail());
607	        boolean duplicate = this.clinicService.findAllOwners().stream()
608	            .anyMatch(existing -> identity.equals(
609	                personalIdentity(toE164OrNull(existing.getTelephone()), existing.getEmail())));
610	        if (duplicate) {
611	            String householdId = Households.householdId(owner.getLastName(), owner.getPostcode());
612	            throw new DuplicateIdentityException(
613	                Households.identityKey(owner.getTelephone(), owner.getEmail(), householdId));
614	        }
615	    }
616	
617	    /**
618	     * Builds the identity-bearing prefix of the {@code identityKey} used for duplicate detection:
619	     * the normalized telephone and email joined with {@code '|'}, lower-casing the email (the form it
620	     * is stored in, see {@link #normalizeEmail}) so addresses differing only in letter case still match.
621	     */
622	    private String personalIdentity(String telephone, String email) {
623	        String normalizedEmail = email == null ? "" : email.toLowerCase(java.util.Locale.ROOT);
624	        return (telephone == null ? "" : telephone) + "|" + normalizedEmail;
625	    }
626	
627	    /**
628	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
629	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number, or
630	     * when its national-number length does not match its country code.
631	     */
632	    private String toE164OrNull(String telephone) {
633	        try {
634	            return normalizeTelephone(telephone);
635	        } catch (InvalidTelephoneException e) {
636	            return null;
637	        }
638	    }
639	
640	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
641	    @Override
642	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
643	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
644	        if (currentOwner == null) {
645	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
646	        }
647	        currentOwner.setAddress(ownerFieldsDto.getAddress());
648	        currentOwner.setCity(ownerFieldsDto.getCity());
649	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
650	        currentOwner.setLastName(ownerFieldsDto.getLastName());
651	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
652	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
653	        this.clinicService.saveOwner(currentOwner);
654	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
655	    }
656	
657	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
658	    @Transactional
659	    @Override
660	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
661	        Owner owner = this.clinicService.findOwnerById(ownerId);
662	        if (owner == null) {
663	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
664	        }
665	        this.clinicService.deleteOwner(owner);
666	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
667	    }
668	
669	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
670	    @Override
671	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
672	        Owner owner = this.clinicService.findOwnerById(ownerId);
673	        if (owner == null) {
674	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
675	        }
676	        HttpHeaders headers = new HttpHeaders();
677	        Pet pet = petMapper.toPet(petFieldsDto);
678	        owner.setId(ownerId);
679	        pet.setOwner(owner);
680	        pet.getType().setName(null);
681	        this.clinicService.savePet(pet);
682	        PetDto petDto = petMapper.toPetDto(pet);
683	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
684	            .buildAndExpand(pet.getId()).toUri());
685	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
686	    }
687	
688	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
689	    @Override
690	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
691	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
692	        if (currentOwner != null) {
693	            Pet currentPet = this.clinicService.findPetById(petId);
694	            if (currentPet != null) {
695	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
696	                currentPet.setName(petFieldsDto.getName());
697	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
698	                this.clinicService.savePet(currentPet);
699	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
700	            }
701	        }
702	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
703	    }
704	
705	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
706	    @Override
707	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
708	        HttpHeaders headers = new HttpHeaders();
709	        Visit visit = visitMapper.toVisit(visitFieldsDto);
710	        Pet pet = new Pet();
711	        pet.setId(petId);
712	        visit.setPet(pet);
713	        this.clinicService.saveVisit(visit);
714	        VisitDto visitDto = visitMapper.toVisitDto(visit);
715	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
716	            .buildAndExpand(visit.getId()).toUri());
717	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
718	    }
719	
720	
721	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
722	    @Override
723	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
724	        Owner owner = this.clinicService.findOwnerById(ownerId);
725	        if (owner != null) {
726	            Pet pet = owner.getPet(petId);
727	            if (pet != null) {
728	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
729	            }
730	        }
731	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
732	    }
733	}
